class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        queue = deque()
        ans = []
        l = 0
        n = len(nums)

        for r in range(n):
            while queue and nums[queue[-1]] < nums[r]:
                queue.pop()

            queue.append(r)

            while queue[0] < r - k + 1:
                queue.popleft()

            if r - l + 1 >= k:
                ans.append(nums[queue[0]])

        return ans
